    if len(numbers_list) == 2:
        return lcm(numbers_list[0], numbers_list[1])
    elif len(numbers_list) > 2:
        numbers_list2 = [lcm(numbers_list[0], numbers_list[1])]
        numbers_list2.extend(numbers_list[2:])
        return multi_lcm(numbers_list2)


