def cross(a, b):
    return a.real * b.imag - a.imag * b.real


def ccw(p1, p2, p3):
    return cross(p2 - p1, p3 - p1)


# http://en.wikipedia.org/wiki/Graham_scan
def graham_scan(p):
    left = min(p, key=operator.attrgetter('imag', 'real'))
    p.remove(left)

    def sin(target):
        return cross(target - left, 1) / abs(target - left)
    p.sort(key=sin, reverse=True)
    p = [left] + p

    m = 0
    for i in range(1, len(p)):
        while ccw(p[m - 1], p[m], p[i]) < 0:
            if m > 0:
                m -= 1
            elif i == len(p) - 1:
                break
            else:
                i += 1
        m += 1
        p[m], p[i] = p[i], p[m]
    return p[:m + 1]


