    used = [False] * (n + 1)
    def dfs(v):
        if used[v]:
            return 0
        used[v] = True
        stack = [(~v, -1, -1), (v, -1, -1)]
        while stack:
            v, p, i = stack.pop()
            if v >= 0:
                for nv, i in E[v]:
                    if used[nv]:
                        continue
                    used[nv] = True
                    stack.append((~nv, v, i))
