def combs_mod(n,k,mod):
  #nC0からnCkまで
  inv = [1]*(k+1)
  for i in range(1,k+1):
    inv[i] = pow(i,mod-2,mod)
  ans = [1]*(k+1)
  for i in range(1,k+1):
    ans[i] = ans[i-1]*(n+1-i)*inv[i]%mod
  return ans
def solve():
  mod = 998244353
  N, K = map(int, input().split())
  ans = 0
  if K<N:
    return ans
  com = combs_mod(K,K,mod)
  for r in range(K+1):
    b = K-r
    if r<b or r<N:
      continue
    ans += com[r]
    if r-b<N:
      ans -= com[max(b,N)-1+b-r]
    ans %= mod
  return ans
print(solve())

