        route.push(None)
        dfs_stack = [(root, route[-1])]
        while dfs_stack:
            u, prev = dfs_stack.pop()
            if u in visited:
                continue

            parent[u] = prev
            if prev is not None:
                child[prev].append(u)
            visited |= {u}
            prenum[u] = lowest[u] = len(visited)

            while route[-1] != prev:
                route.pop()
            backtrack[u] = route & g[u]
            route.push(u)

            dfs_stack.extend((v, u) for v in g[u] - visited) 

        from heapq import heappush, heappop
        heap = []
        for i in range(v):
            if backtrack[i]:
                heappush(heap, (prenum[i], i))
        while heap:
