    for _ in range(n):
      lst = list(map(int, input().split()))
      k = lst[0]
      line = [(acc + i, lst[i * 2 + 1], lst[i * 2 + 2]) for i in range(k)]
      acc += k
      lines.append(line)

    num = acc - 1
    edges = [[] for _ in range(num * (m + 1) + 2)]
    for line1, line2 in zip(lines, lines[1:]):  
      for acc1, x1, d1 in line1:
        for acc2, x2, d2 in line2:
          cost = (d1 + d2) * abs(x1 - x2)
          n1 = acc1
          n2 = acc2
          for j in range(m + 1):
            edges[n1].append((n2, cost))
            n1 += num
            n2 += num

    for line1, line2 in zip(lines, lines[2:]):  
      for acc1, x1, d1 in line1:
        for acc2, x2, d2 in line2:
          cost = (d1 + d2) * abs(x1 - x2)
          n1 = acc1
          n2 = acc2 + num
          for j in range(m):
            edges[n1].append((n2, cost))
            n1 += num
            n2 += num

    for acc, _, _ in lines[0]:
      edges[0].append((acc, 0))
    if m >= 1:
